using MediatR; using Microsoft.AspNetCore.Http; using Microsoft.AspNetCore.Routing; namespace JTradeERP.Application.Features.MasterData.Categories.DeactivateCategory; public static class DeactivateCategoryEndpoint { public static void Map(IEndpointRouteBuilder e)=>e.MapPost("/categories/{id:guid}/deactivate",async(Guid id,ISender s,CancellationToken ct)=>Results.Ok(await s.Send(new DeactivateCategoryCommand(id),ct))); }
